```sql
SELECT COUNT(*) FROM singer;
```

```sql
SELECT T1.Name, T1.Capacity FROM stadium AS T1 INNER JOIN (
    SELECT Stadium_ID, AVG(Average) as Average FROM concert GROUP BY Stadium_ID
) AS T2 ON T1.Stadium_ID = T2.Stadium_ID ORDER BY T2.Average DESC LIMIT 1;
```

```sql
SELECT Name FROM stadium WHERE Stadium_ID NOT IN (
  SELECT Stadium_ID FROM concert
) AND Stadium_ID NOT IN (
  SELECT Stadium_ID FROM singer_in_concert
);
```
